script:
// Fuel Efficiency -- self-contained Custom HTML Block, same pattern as Fleet
// Audit: `root_element` is this block's shadow root; every number comes from
// app_apis.fuel_efficiency, which checks a fuel-card export against IM -- each
// truck's GPS distance and, when uploaded, IM's Fill-Drain and Fuel
// Consumption reports for the same dates. A truck's status is its fuel against
// its distance; where it was when it filled up is not used.
//
// Language: the page has its own Arabic / English button. It switches only
// this page (remembered in this browser), never the user's desk language: the
// page's words come from get_translations (app_apis/translations/ar.csv) and
// every server call carries `lang`, so findings and notes come back in it too.
// The CSS uses logical properties, so the layout mirrors when it is Arabic.
// The filters sit under the column headings; the table head is built once per
// view and only the body is redrawn, so typing in a filter never loses focus.

(function () {
	var root = root_element.querySelector(".fue");
	var M = "app_apis.fuel_efficiency.";
	var CTX = "Fuel Efficiency";
	var LANG = "en", DICT = {}, DICT_LOADED = false;

	function t(text, args) {
		if (!text || typeof text !== "string") return text;
		var s = LANG === "ar" ? (DICT[text + ":" + CTX] || DICT[text] || text) : text;
		(args || []).forEach(function (a, i) { s = s.split("{" + i + "}").join(a); });
		return s;
	}
	// The analysis writes its progress in English; shown in the page's language.
	var PROGRESS = ["Reading the files…", "Matching plates to the IM fleet…", "Reading GPS {0} of {1}: {2}", "Saving…",
		"Done: {0} trucks flagged", "Queued", "Running", "Done", "Failed", "Cancelled"];
	function t_progress(text) {
		if (LANG !== "ar" || !text) return text;
		for (var i = 0; i < PROGRESS.length; i++) {
			var pattern = PROGRESS[i].replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\\\{(\d)\\\}/g, "(.+?)");
			var m = String(text).match(new RegExp("^" + pattern + "$"));
			if (m) return t(PROGRESS[i], m.slice(1));
		}
		return text;
	}

	var STATUSES = ["Theft likely", "Suspicious", "OK"];
	var TONE = { "Theft likely": "red", "Suspicious": "amber", "OK": "green" };
	var LEVEL_TONE = { 2: "red", 1: "amber", 0: "gray" };
	var TRUCK_KEYS = ["verdict", "plate", "vehicle", "checked", "rate", "finding", "risk"];
	var FILL_KEYS = ["fplate", "station", "driver", "flag"];
	var XLSX = { restrictions: { allowed_file_types: [".xlsx"] } };
	var JUDGE_KM = 300;
	var can_run = frappe.user.has_role(["System Manager", "Technical"]);
	var HINT, BASIS, FINDINGS, FLAGS;
	var imp = null, info = {}, view = "trucks", start = 0, limit = 50, poller = null, seq = 0, pick = null;
	var f = {};
	TRUCK_KEYS.concat(FILL_KEYS).forEach(function (k) { f[k] = ""; });
	var sorts = { trucks: null, fills: null };  // {key, dir} picked from a column heading
	// "" shows each truck by its most exact source (its status); a source key
	// shows every truck worked out from that one source, worked out at analysis.
	var by = "";

	// Word tables, rebuilt whenever the language changes.
	function words() {
		HINT = {
			"Theft likely": t("Strong signs the fuel did not go into the truck. Check these first."),
			"Suspicious": t("Something unusual that is worth a look."),
			"OK": t("Nothing unusual found."),
		};
		BASIS = { "GPS": t("GPS"), "IM report": t("IM report"), "Odometer (card)": t("typed odometer") };
		FINDINGS = [
			["burn", t("High consumption")], ["missing", t("Paid but not in the tank")], ["drain", t("Fuel drained")],
			["odometer", t("Odometer mismatch")], ["no_move", t("Refuelled without driving")], ["quick", t("Refilled too soon")],
			["big", t("Large fills")], ["no_gps", t("GPS problem")], ["sensor", t("Tank sensor unreliable")],
			["trip", t("Bought more than it could burn and hold")],
		];
		FLAGS = [
			["no_move", t("Refuelled without driving")], ["quick", t("Refilled too soon")], ["big", t("Large fill")],
			["over_tank", t("Bigger than the tank")], ["odometer", t("Odometer went backwards")],
			["trip", t("Beyond what it could burn and hold")],
		];
	}

	var el = {};
	["title", "when", "headright", "notes", "progress", "pfill", "ptext", "cancel", "cards", "stats", "bar", "wrap", "foot"].forEach(function (k) {
		el[k] = root.querySelector(".fue-" + k);
	});

	// Stops a queued or running analysis; the last finished results stay.
	el.cancel.addEventListener("click", function () {
		if (!imp) return;
		frappe.confirm(esc(t("Stop this analysis? The results of the last finished run stay as they are.")), function () {
			call("cancel_analysis", { fuel_import: imp }).then(function () {
				stop_watch();
				load_imports(imp);
			});
		});
	});

	// Dialogs live outside the shadow root, so they carry their own CSS.
	var DIALOG_CSS =
		"<style>.fue-dlg{font-size:13px;line-height:1.55}" +
		".fue-dlg table{width:100%;border-collapse:collapse;font-size:12.5px}" +
		".fue-dlg th{font-size:11px;color:var(--text-muted);font-weight:600;padding:8px 10px;text-align:start;white-space:nowrap;border-bottom:1px solid var(--border-color)}" +
		".fue-dlg td{padding:8px 10px;border-bottom:1px solid var(--border-color);vertical-align:top;text-align:start}" +
		".fue-dlg tr:last-child td{border-bottom:none}" +
		".fue-dlg .num{text-align:end;white-space:nowrap}.fue-dlg .nowrap{white-space:nowrap}" +
		".fue-dlg .dim{color:var(--text-muted);font-size:11.5px}" +
		".fue-dlg .yes{color:#1f7a44}.fue-dlg .no{color:#c2413b;font-weight:600}.fue-dlg .warn{color:#b86e00;font-weight:600}" +
		".fue-dlg .reason{min-width:200px}.fue-dlg .mono{font-family:var(--font-stack-mono,monospace);direction:ltr;unicode-bidi:isolate}" +
		".fue-dlg .pill{display:inline-flex;align-items:center;gap:5px;padding:2px 10px;border-radius:999px;font-size:11.5px;font-weight:600;white-space:nowrap}" +
		".fue-dlg .pill.red{background:rgba(224,82,75,.14);color:#b3261e}.fue-dlg .pill.amber{background:rgba(232,163,61,.18);color:#8a5300}" +
		".fue-dlg .pill.green{background:rgba(58,167,109,.15);color:#1f7a44}.fue-dlg .pill.gray{background:rgba(120,120,120,.14);color:var(--text-muted)}" +
		".fue-dlg .dot{width:8px;height:8px;border-radius:50%;background:currentColor;display:inline-block;flex:none}" +
		".fue-dlg .red .dot{color:#e0524b}.fue-dlg .amber .dot{color:#e8a33d}.fue-dlg .green .dot{color:#3aa76d}.fue-dlg .gray .dot{color:#98a1a9}" +
		".fue-dlg-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:14px}" +
		".fue-sec{margin:16px 0 0}.fue-sec-t{font-size:11.5px;font-weight:600;color:var(--text-muted);margin-bottom:6px}" +
		".fue-why{list-style:none;margin:0;padding:0}.fue-why li{display:flex;gap:10px;align-items:flex-start;padding:4px 0}" +
		".fue-why .dot{margin-top:7px}" +
		".fue-facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin-top:16px}" +
		".fue-fact{border:1px solid var(--border-color);border-radius:10px;padding:10px 12px}" +
		".fue-fact .k{font-size:11.5px;font-weight:600;color:var(--text-muted);margin-bottom:4px}" +
		".fue-dlg-wrap{overflow:auto;max-height:50vh;border:1px solid var(--border-color);border-radius:10px}" +
		".fue-by-wrap{overflow-x:auto;border:1px solid var(--border-color);border-radius:10px}" +
		".fue-dlg th.num{text-align:end}.fue-dlg .fue-by tr.used td{background:rgba(58,167,109,.08)}" +
		".fue-dlg .tag{display:inline-block;margin-top:4px;padding:1px 8px;border-radius:999px;font-size:11px;font-weight:600;" +
			"background:rgba(58,167,109,.16);color:#1f7a44}" +
		".fue-by-note{margin-top:6px}" +
		".fue-help-body>ul{padding-inline-start:18px}.fue-help-body li{margin:5px 0}.fue-help-body ul ul{margin-top:4px}" +
		".fue-help-body ul.fue-why{padding:0}</style>";

	function dlg(cls) {
		return '<div class="fue-dlg' + (cls ? " " + cls : "") + '" dir="' + (shown() === "ar" ? "rtl" : "ltr") + '">';
	}
	function esc(v) {
		return frappe.utils.escape_html(String(v === undefined || v === null ? "" : v));
	}
	function known(v) {
		return v !== null && v !== undefined && v !== "";
	}
	function fmt(v, d) {
		var n = Number(v);
		if (!isFinite(n)) return String(v === undefined || v === null ? "" : v);
		return n.toLocaleString("en-US", { maximumFractionDigits: d || 0, minimumFractionDigits: d || 0 });
	}
	function num(v, d) {
		return known(v) ? esc(fmt(v, d)) : '<span class="dim">—</span>';
	}
	function signed(v) {
		return known(v) ? (Number(v) > 0 ? "+" : "") + esc(fmt(v)) + "%" : '<span class="dim">—</span>';
	}
	function pill(status) {
		return status ? '<span class="pill ' + (TONE[status] || "gray") + '"><span class="dot"></span>' + esc(t(status)) + "</span>" : "";
	}
	function when(v) {
		return v ? esc(frappe.datetime.str_to_user(v)) : "";
	}
	// Line icons drawn inline: the block lives in a shadow root, where the
	// desk's icon sprite cannot be referenced.
	var ICON = {
		theft: '<path d="M12 16h.01"/><path d="M12 8v4"/><path d="M15.31 2a2 2 0 0 1 1.42.59l4.68 4.68A2 2 0 0 1 22 8.69v6.62a2 2 0 0 1-.59 1.42l-4.68 4.68a2 2 0 0 1-1.42.59H8.69a2 2 0 0 1-1.42-.59l-4.68-4.68A2 2 0 0 1 2 15.31V8.69a2 2 0 0 1 .59-1.42l4.68-4.68A2 2 0 0 1 8.69 2z"/>',
		warn: '<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"/><path d="M12 9v4"/><path d="M12 17h.01"/>',
		ok: '<circle cx="12" cy="12" r="10"/><path d="m9 12 2 2 4-4"/>',
		fuel: '<path d="M3 22h12"/><path d="M4 9h10"/><path d="M14 22V4a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v18"/><path d="M14 13h2a2 2 0 0 1 2 2v2a2 2 0 0 0 4 0V9.83a2 2 0 0 0-.59-1.42L18 5"/>',
		truck: '<path d="M14 18V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v11a1 1 0 0 0 1 1h2"/><path d="M15 18H9"/><path d="M19 18h2a1 1 0 0 0 1-1v-3.65a1 1 0 0 0-.22-.62l-3.48-4.35A1 1 0 0 0 17.52 8H14"/><circle cx="17" cy="18" r="2"/><circle cx="7" cy="18" r="2"/>',
		gps: '<path d="M20 10c0 5-5.54 10.19-7.4 11.8a1 1 0 0 1-1.2 0C9.54 20.19 4 15 4 10a8 8 0 0 1 16 0"/><circle cx="12" cy="10" r="3"/>',
		sensor: '<path d="m12 14 4-4"/><path d="M3.34 19a10 10 0 1 1 17.32 0"/>',
		drop: '<path d="M12 22a7 7 0 0 0 7-7c0-2-1-3.9-3-5.5s-3.5-4-4-6.5c-.5 2.5-2 4.9-4 6.5C6 11.1 5 13 5 15a7 7 0 0 0 7 7z"/>',
		cash: '<rect width="20" height="12" x="2" y="6" rx="2"/><circle cx="12" cy="12" r="2"/><path d="M6 12h.01M18 12h.01"/>',
		missing: '<path d="M18.72 13.19C18.29 11.86 17.38 10.61 16 9.5c-2-1.6-3.5-4-4-6.5a10.7 10.7 0 0 1-.88 2.59"/><path d="m2 2 20 20"/><path d="M8.8 8.8A11 11 0 0 1 8 9.5C6 11.1 5 13 5 15a7 7 0 0 0 13.22 3.21"/>',
		drain: '<path d="M12 17V3"/><path d="m6 11 6 6 6-6"/><path d="M19 21H5"/>',
		link: '<path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/>',
	};
	var STATUS_ICON = { "Theft likely": "theft", "Suspicious": "warn", "OK": "ok" };
	function icon(name, size) {
		return '<svg class="fue-svg" viewBox="0 0 24 24" width="' + (size || 18) + '" height="' + (size || 18) +
			'" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
			ICON[name] + "</svg>";
	}
	function call(method, args) {
		return frappe.call({ method: M + method, args: args || {} }).then(function (r) {
			return (r && r.message) || {};
		});
	}
	// The distance the L/100 km was worked out over, and how much to trust it.
	function km_used(r) {
		if (r.lp100_basis === "IM report") return r.im_km;
		if (r.lp100_basis === "Odometer (card)") return r.odometer_km;
		return known(r.gps_km) ? r.gps_km : r.im_km;
	}
	// Colour for an L/100 km worked out over `km`: amber above normal, red above
	// the theft limit (never by the typed odometer), none under JUDGE_KM.
	function tone(r, lp, km, typed) {
		if (!known(lp) || Number(km) < JUDGE_KM) return "";
		var v = Number(lp);
		if (!typed && v > Number(r.theft_lp100)) return "no";
		return v > Number(r.normal_lp100) ? "warn" : "";
	}
	function lp_tone(r) {
		return tone(r, r.lp100, km_used(r), r.lp100_basis === "Odometer (card)");
	}
	function checked(r) {
		return String(r.checked_with || "Fuel card only").split(" + ").map(function (x) { return t(x); }).join(" + ");
	}
	function fill_note_text(r) {
		return r.flags || "";
	}

	// ------------------------------------------------------ header, language

	function render_header() {
		el.title.textContent = t("Fuel Efficiency");
		el.cancel.textContent = t("Cancel analysis");
		el.cancel.style.display = can_run ? "" : "none";
		el.headright.innerHTML =
			'<select class="fue-pick" style="display:none" title="' + esc(t("Fuel report")) + '"></select>' +
			(can_run ? '<button class="btn btn-primary btn-sm fue-upload">' + esc(t("New report")) + "</button>" : "") +
			(can_run ? '<button class="btn btn-default btn-sm fue-addim fue-needs">' + esc(t("Add IM reports")) + "</button>" : "") +
			(can_run ? '<button class="btn btn-default btn-sm fue-rerun fue-needs">' + esc(t("Re-analyse")) + "</button>" : "") +
			(can_run ? '<button class="btn btn-default btn-sm fue-limits fue-needs">' + esc(t("Limits")) + "</button>" : "") +
			'<button class="btn btn-default btn-sm fue-export fue-needs">' + esc(t("Export")) + "</button>" +
			// The report's link for anyone without an account: one click copies it.
			(can_run ? '<button class="btn btn-default btn-sm fue-copy fue-needs">' + icon("link", 14) + esc(t("Copy report link")) + "</button>" +
				'<button class="btn btn-default btn-sm fue-unshare" style="display:none">' + esc(t("Stop sharing")) + "</button>" : "") +
			'<button class="btn btn-default btn-sm fue-help">' + esc(t("How it works")) + "</button>" +
			// Each language names itself, so the button reads right to whoever needs it.
			'<button class="btn btn-default btn-sm fue-lang" lang="' + (LANG === "ar" ? "en" : "ar") + '">' +
				(LANG === "ar" ? "English" : "العربية") + "</button>";
		pick = el.headright.querySelector(".fue-pick");
		pick.addEventListener("change", function () { select(pick.value); });
		on_click(".fue-upload", function () { upload(""); });
		on_click(".fue-addim", function () { if (imp) upload(imp); });
		on_click(".fue-rerun", rerun);
		on_click(".fue-limits", limits_dialog);
		on_click(".fue-copy", copy_link);
		on_click(".fue-unshare", stop_sharing);
		on_click(".fue-export", export_csv);
		on_click(".fue-help", help);
		on_click(".fue-lang", function () { set_lang(LANG === "ar" ? "en" : "ar"); });
	}

	function on_click(selector, fn) {
		var node = el.headright.querySelector(selector);
		if (node) node.addEventListener("click", fn);
	}

	// The language actually on screen: Arabic only once its words are here.
	function shown() {
		return LANG === "ar" && DICT_LOADED ? "ar" : "en";
	}

	function set_lang(lang) {
		LANG = lang === "ar" ? "ar" : "en";
		try {
			localStorage.setItem("fue_lang", LANG);
		} catch (e) {
			// private window or blocked storage: the choice just is not remembered
		}
		// The buttons show at once; the page never waits on the Arabic words,
		// and stays usable in English if they cannot be fetched.
		render_header();
		var ready = LANG === "ar" && !DICT_LOADED
			? call("get_translations", { lang: "ar" }).then(function (d) { DICT = d || {}; DICT_LOADED = true; }, function () {})
			: Promise.resolve();
		return ready.then(paint);
	}

	function paint() {
		root.setAttribute("dir", shown() === "ar" ? "rtl" : "ltr");
		root.setAttribute("lang", shown());
		words();
		render_header();
		load_imports(imp);
	}

	function load_imports(choose) {
		call("list_imports").then(function (list) {
			list = Array.isArray(list) ? list : [];
			pick.innerHTML = list.map(function (r) {
				return '<option value="' + esc(r.name) + '">' + esc(r.title || r.name) +
					(r.status !== "Done" ? " (" + esc(t(r.status)) + ")" : "") + "</option>";
			}).join("");
			pick.style.display = list.length ? "" : "none";
			el.headright.querySelectorAll(".fue-needs").forEach(function (b) { b.style.display = list.length ? "" : "none"; });
			if (!list.length) {
				imp = null;
				["when", "notes", "cards", "stats", "bar", "foot"].forEach(function (k) { el[k].innerHTML = ""; });
				el.wrap.innerHTML = '<div class="fue-empty"><div class="big">' + esc(t("No fuel report yet")) + '</div><ol class="steps">' +
					"<li>" + esc(t("Export the fuel-card report from the fuel company (.xlsx).")) + "</li>" +
					"<li>" + esc(t("From IM, export the Fill-Drain and Fuel Consumption reports for the same dates.")) + "</li>" +
					"<li>" + esc(t("Press New report and choose the files.")) + "</li></ol></div>";
				return;
			}
			var keep = choose && list.some(function (r) { return r.name === choose; }) ? choose : list[0].name;
			select(keep);
		});
	}

	function select(name) {
		imp = name;
		pick.value = name;
		start = 0;
		if (name !== info.name_shown) by = "";  // another report may not have the source picked
		info.name_shown = name;
		call("get_progress", { fuel_import: name }).then(function (p) {
			if (p.status === "Queued" || p.status === "Running") watch(p);
			else stop_watch();
			load();
		});
	}

	function load() {
		if (!imp) return;
		call("get_summary", { fuel_import: imp, lang: shown(), by: by }).then(function (s) {
			s.name_shown = imp;
			info = s;
			update_share();
			update_limits();
			render_summary();
			render_bar();
			build_table();
			load_rows();
		});
	}

	// ------------------------------------------------------------- summary

	function render_summary() {
		var d = info.import || {}, s = info.sensor || {};
		// Shown from one source: the cards count that source's own statuses.
		var vw = by && info.view ? info.view : null;
		var v = (vw ? vw.verdicts : info.verdicts) || {};
		var risk_l = vw ? vw.liters_at_risk : d.liters_at_risk, risk_sar = vw ? vw.cost_at_risk : d.cost_at_risk;

		var parts = [];
		if (d.period_from) {
			parts.push(esc(t("Fuel card")) + " " + esc(frappe.datetime.str_to_user(d.period_from)) + " – " + esc(frappe.datetime.str_to_user(d.period_to)));
		}
		if (d.analysed_on) parts.push(esc(t("analysed {0}", [frappe.datetime.str_to_user(d.analysed_on)])));
		if (d.status === "Failed") parts.push('<span class="no">' + esc(t("The analysis failed")) + "</span>");
		if (d.progress === "Cancelled") {
			parts.push('<span class="warn">' + esc(d.analysed_on
				? t("The last analysis was cancelled; these are the results of the one before.")
				: t("The analysis was cancelled.")) + "</span>");
		}
		el.when.innerHTML = parts.join(" · ");

		var chip = function (label, period) {
			return '<span class="fue-chip' + (period ? " ok" : "") + '">' + esc(label) + ": " + esc(period || t("not uploaded")) + "</span>";
		};
		el.notes.innerHTML =
			'<div class="fue-chips"><span>' + esc(t("IM reports")) + "</span>" +
				chip(t("Fill-Drain"), d.fill_drain_period) + chip(t("Fuel Consumption"), d.consumption_period) +
				(can_run && (!d.fill_drain_period || !d.consumption_period) ? '<a href="#" class="fue-link fue-addim2">' + esc(t("Add")) + "</a>" : "") +
			"</div>" +
			(info.notes || []).map(function (n) {
				return '<div class="' + (n.warn ? "fue-warn" : "fue-note") + '">' + esc(n.text) + "</div>";
			}).join("");
		var add2 = el.notes.querySelector(".fue-addim2");
		if (add2) add2.addEventListener("click", function (e) { e.preventDefault(); upload(imp); });

		el.cards.innerHTML = STATUSES.map(function (st) {
			return '<button type="button" class="fue-card ' + TONE[st] + (f.verdict === st ? " on" : "") + '" data-verdict="' + esc(st) + '"' +
				' aria-pressed="' + (f.verdict === st) + '">' +
				'<span class="fue-card-ico">' + icon(STATUS_ICON[st], 22) + "</span>" +
				'<span class="fue-card-body"><span class="fue-card-label">' + esc(t(st)) + "</span>" +
				'<span class="fue-card-n">' + num(v[st] || 0) + " <small>" + esc(t("trucks")) + "</small></span>" +
				'<span class="fue-card-hint">' + esc(HINT[st]) + "</span></span></button>";
		}).join("") +
			'<div class="fue-card risk"><span class="fue-card-ico">' + icon("fuel", 22) + "</span>" +
				'<span class="fue-card-body"><span class="fue-card-label">' + esc(t("Stolen fuel")) + "</span>" +
				'<span class="fue-card-n">' + num(risk_l) + " <small>" + esc(t("liters")) + "</small></span>" +
				'<span class="fue-card-hint">' + esc(t("Burned above the fuel limit · about {0} SAR", [fmt(risk_sar)])) + "</span></span></div>";
		el.cards.querySelectorAll("[data-verdict]").forEach(function (b) {
			b.addEventListener("click", function () {
				var st = b.getAttribute("data-verdict");
				f.verdict = f.verdict === st ? "" : st;
				start = 0;
				if (view !== "trucks") {
					view = "trucks";
					build_table();
				} else {
					var head = el.wrap.querySelector('select[data-f="verdict"]');
					if (head) {
						head.value = f.verdict;
						head.classList.toggle("on", !!f.verdict);
					}
				}
				render_summary();
				render_bar();
				load_rows();
			});
		});

		var stats = [
			["truck", d.vehicles, t("trucks")], ["gps", d.tracked_vehicles, t("checked with GPS")],
			["sensor", d.sensor_vehicles, t("with fuel sensor")], ["fuel", d.fills, t("fills")],
			["drop", d.liters, t("liters bought")], ["cash", d.cost, t("SAR spent")],
		];
		if (s.trucks) {
			stats.push(["missing", s.missing_l, t("liters paid but not seen in the tank")]);
			stats.push(["drain", s.drained_l, t("liters drained")]);
		}
		el.stats.innerHTML = (vw ? '<div class="fue-view-note">' + esc(vw.ready
			? t("Worked out from {0} for every truck. {1} trucks have no {0} and show a dash.", [source_name(by), fmt(vw.missing)])
			: t("Re-analyse this report once to see it worked out from each source.")) + "</div>" : "") +
			stats.map(function (x) {
				return '<span class="fue-stat">' + icon(x[0], 15) + "<b>" + num(x[1]) + "</b> " + esc(x[2]) + "</span>";
			}).join("");
	}

	function source_name(src) {
		return { card: t("Typed odometer"), gps: t("GPS track"), fill_drain: t("Fill-Drain"), consumption: t("Fuel Consumption") }[src] ||
			t("Best source");
	}

	// ------------------------------------------------- tabs and the table

	function render_bar() {
		var trucks = view === "trucks", d = info.import || {};
		var n = (trucks ? TRUCK_KEYS : FILL_KEYS).filter(function (k) { return f[k]; }).length;
		// Which source every truck is worked out from; the IM reports only when uploaded.
		var sources = ["", "card", "gps"].concat(d.fill_drain_period ? ["fill_drain"] : [], d.consumption_period ? ["consumption"] : []);
		el.bar.innerHTML =
			'<div class="fue-tabs">' +
				'<a href="#" data-view="trucks" class="' + (trucks ? "on" : "") + '">' + esc(t("Trucks")) + "</a>" +
				'<a href="#" data-view="fills" class="' + (trucks ? "" : "on") + '">' + esc(t("Fills")) + "</a>" +
			"</div>" +
			(trucks ? '<div class="fue-by-pick"><span>' + esc(t("Worked out from")) + '</span><div class="fue-tabs">' +
				sources.map(function (src) {
					return '<a href="#" data-by="' + src + '" class="' + (src === by ? "on" : "") + '">' + esc(source_name(src)) + "</a>";
				}).join("") + "</div></div>" : "") +
			'<div class="fue-bar-end">' + (n
				? '<a href="#" class="fue-link fue-clear">' + esc(t("Clear filters")) + " (" + n + ")</a>"
				: '<span class="dim">' + esc(t("Filter from the column headings.")) + "</span>") +
			"</div>";
		el.bar.querySelectorAll("[data-view]").forEach(function (a) {
			a.addEventListener("click", function (e) {
				e.preventDefault();
				view = a.getAttribute("data-view");
				start = 0;
				render_bar();
				build_table();
				load_rows();
			});
		});
		// Switching the source only reads what the analysis stored.
		el.bar.querySelectorAll("[data-by]").forEach(function (a) {
			a.addEventListener("click", function (e) {
				e.preventDefault();
				by = a.getAttribute("data-by");
				start = 0;
				load();
			});
		});
		var clear = el.bar.querySelector(".fue-clear");
		if (clear) clear.addEventListener("click", function (e) {
			e.preventDefault();
			(view === "trucks" ? TRUCK_KEYS : FILL_KEYS).forEach(function (k) { f[k] = ""; });
			start = 0;
			render_summary();
			render_bar();
			build_table();
			load_rows();
		});
	}

	function options(key, list) {
		return list.map(function (x) {
			return '<option value="' + esc(x[0]) + '"' + (x[0] === f[key] ? " selected" : "") + ">" + esc(x[1]) + "</option>";
		}).join("");
	}
	function choice(key, list) {
		return '<select data-f="' + key + '"' + (f[key] ? ' class="on"' : "") + '><option value="">' + esc(t("All")) + "</option>" +
			options(key, list) + "</select>";
	}
	function typed(key, placeholder) {
		return '<input data-f="' + key + '" type="search"' + (f[key] ? ' class="on"' : "") +
			' placeholder="' + esc(placeholder) + '" value="' + esc(f[key]) + '">';
	}
	function vehicle_choice() {
		var group = function (label, list) {
			return list.length ? '<optgroup label="' + esc(label) + '">' + options("vehicle", list) + "</optgroup>" : "";
		};
		return '<select data-f="vehicle"' + (f.vehicle ? ' class="on"' : "") + '><option value="">' + esc(t("All")) + "</option>" +
			group(t("Class"), (info.classes || []).map(function (c) { return ["c:" + c, t(c)]; })) +
			group(t("Brand"), (info.brands || []).map(function (b) { return ["b:" + b, b]; })) +
			group(t("Branch"), (info.branches || []).map(function (b) { return ["r:" + b, b]; })) + "</select>";
	}

	// [heading, css class, filter under it, sort key]
	function columns() {
		if (view === "trucks") {
			return [
				[t("Status"), "", choice("verdict", STATUSES.map(function (s) { return [s, t(s)]; })), "verdict"],
				[t("Plate"), "", typed("plate", t("Plate or driver")), "plate"],
				[t("Vehicle"), "", vehicle_choice(), "vehicle"],
				[by ? t("Fuel counted") : t("Fuel bought"), "num", "", "liters"],
				[t("Distance"), "num", choice("checked", [["gps", t("Checked with GPS")], ["sensor", t("With fuel sensor")], ["card", t("Fuel card only")]]), "km"],
				[by ? t("Worked out from") : t("Report used"), "", "", by ? "" : "used"],
				[t("L/100 km"), "num", choice("rate", [["above_normal", t("Above normal")], ["above_theft", t("Above theft limit")], ["unjudged", t("Not judged")]]), "rate"],
				[t("Main reason"), "", choice("finding", FINDINGS), "finding"],
				[t("Stolen fuel"), "num", choice("risk", [["yes", t("With stolen fuel")]]), "risk"],
			];
		}
		return [
			[t("Plate"), "", typed("fplate", t("Plate")), "fplate"],
			[t("Time"), "", "", "time"],
			[t("Station"), "", typed("station", t("Station or area")), "station"],
			[t("Liters"), "num", "", "liters"],
			[t("Odometer"), "num", "", "odometer"],
			[t("Odometer km since last fill"), "num", "", "odo_km"],
			[t("GPS km since last fill"), "num", "", "gps_km"],
			[t("Driver"), "", typed("driver", t("Driver name")), "driver"],
			[t("Notes"), "", choice("flag", FLAGS), "flag"],
		];
	}

	function build_table() {
		if (!imp) return;
		var cols = columns(), s = sorts[view];
		el.wrap.innerHTML = "<table><thead><tr>" +
			cols.map(function (c) {
				var on = !!s && s.key === c[3];
				return '<th class="' + c[1] + '"' + (on ? ' aria-sort="' + (s.dir === "asc" ? "ascending" : "descending") + '"' : "") + ">" +
					(c[3] ? '<button type="button" class="fue-sort' + (on ? " on" : "") + '" data-sort="' + c[3] + '" title="' + esc(t("Sort by this column")) + '">' +
						esc(c[0]) + '<span class="fue-arrow">' + (on ? (s.dir === "asc" ? "▲" : "▼") : "↕") + "</span></button>" : esc(c[0])) + "</th>";
			}).join("") +
			'</tr><tr class="fue-filter-row">' + cols.map(function (c) { return "<th>" + c[2] + "</th>"; }).join("") +
			'</tr></thead><tbody class="fue-body"></tbody></table>';
		el.body = el.wrap.querySelector(".fue-body");
		el.span = cols.length;
		// A heading sorts up, then down, then back to the report's own order.
		el.wrap.querySelectorAll(".fue-sort").forEach(function (b) {
			b.addEventListener("click", function () {
				var key = b.getAttribute("data-sort"), cur = sorts[view];
				sorts[view] = !cur || cur.key !== key ? { key: key, dir: "asc" } : cur.dir === "asc" ? { key: key, dir: "desc" } : null;
				start = 0;
				build_table();
				load_rows();
			});
		});
		el.wrap.querySelectorAll("[data-f]").forEach(function (input) {
			var key = input.getAttribute("data-f");
			var fire = function () {
				f[key] = input.value;
				input.classList.toggle("on", !!input.value);
				start = 0;
				if (key === "verdict") render_summary();
				render_bar();
				load_rows();
			};
			if (input.tagName === "SELECT") input.addEventListener("change", fire);
			else input.addEventListener("input", frappe.utils.debounce(fire, 350));
		});
	}

	function body_message(text) {
		el.body.innerHTML = '<tr><td colspan="' + el.span + '" class="fue-empty">' + esc(text) + "</td></tr>";
	}

	function sort_args(s) {
		return s ? { sort: s.key, order: s.dir } : {};
	}
	function truck_args(extra) {
		return Object.assign({
			fuel_import: imp, verdict: f.verdict, plate: f.plate, vehicle: f.vehicle, checked: f.checked,
			rate: f.rate, finding: f.finding, risk: f.risk, by: by, lang: shown(),
		}, sort_args(sorts.trucks), extra);
	}
	function fill_args(extra) {
		return Object.assign({
			fuel_import: imp, plate_like: f.fplate, station: f.station, driver: f.driver, flag: f.flag, lang: shown(),
		}, sort_args(sorts.fills), extra);
	}

	function load_rows() {
		if (!imp || !el.body) return;
		var mine = ++seq, trucks = view === "trucks";
		body_message(t("Loading…"));
		call(trucks ? "get_vehicles" : "get_fills", trucks ? truck_args({ start: start, limit: limit }) : fill_args({ start: start, limit: limit }))
			.then(function (res) {
				if (mine !== seq) return;  // a newer filter already answered
				var rows = res.rows || [];
				if (!rows.length) body_message(trucks ? t("No trucks match.") : t("No fills match."));
				else if (trucks) render_trucks(rows);
				else el.body.innerHTML = fill_rows(rows, true);
				pager(res);
			});
	}

	function reason(r) {
		return reason_of(r.findings);
	}
	function reason_of(list) {
		list = list || [];
		if (!list.length) return '<span class="dim">' + esc(t("Nothing unusual found.")) + "</span>";
		return '<span class="' + (list[0].level ? "" : "dim") + '">' + esc(list[0].text) + "</span>" +
			(list.length > 1 ? ' <span class="dim">' + esc(t("+{0} more", [list.length - 1])) + "</span>" : "");
	}

	// The source the status came from, named as on the truck's page.
	function used_src(r) {
		var w = (r.by_report || []).filter(function (x) { return x.used; })[0];
		if (w) return w.src;
		// a report analysed before the per-report table
		if (!r.lp100_basis || Number(km_used(r)) < JUDGE_KM) return "";
		return { "GPS": "gps", "IM report": "im", "Odometer (card)": "card" }[r.lp100_basis] || "";
	}
	function used_names(src) {
		return {
			gps: [t("GPS track"), t("IM, read live")], fill_drain: [t("Fill-Drain"), t("IM report")],
			consumption: [t("Fuel Consumption"), t("IM report")], im: [t("IM report"), ""], card: [t("Fuel card"), t("typed odometer")],
		}[src] || [t("Not judged"), ""];
	}
	function used_cell(r) {
		var src = used_src(r), n = used_names(src);
		return (src ? esc(n[0]) : '<span class="dim">' + esc(n[0]) + "</span>") + (n[1] ? '<div class="dim">' + esc(n[1]) + "</div>" : "");
	}
	function used_text(r) {
		var n = used_names(used_src(r));
		return n[1] ? n[0] + " · " + n[1] : n[0];
	}

	// One truck as the chosen source works it out; a dash and the reason where it cannot.
	function view_cells(r, plate, vehicle) {
		var v = r.view, none = '<span class="dim">—</span>';
		if (!v) {
			return "<td>" + none + "</td>" + plate + vehicle + '<td class="num">' + none + '</td><td class="num">' + none + "</td>" +
				'<td><span class="dim">' + esc(r.view_why || "") + "</span></td>" +
				'<td class="num">' + none + '</td><td class="reason">' + none + '</td><td class="num">' + none + "</td>";
		}
		var n = used_names(v.src);
		var dist = known(v.km) ? esc(t("{0} km", [fmt(v.km)])) : none;
		if (v.odo) {
			dist += '<div class="dim">' + esc(v.src === "card" ? t("odometer {0} → {1}", [fmt(v.odo[0]), fmt(v.odo[1])])
				: t("typed odometer in these dates: {0} km", [fmt(v.odo[1] - v.odo[0])])) + "</div>";
		}
		return "<td>" + pill(v.status) + "</td>" + plate + vehicle +
			'<td class="num">' + esc(t("{0} L", [fmt(v.liters)])) + '<div class="dim">' + esc(t("{0} fills after the first", [fmt(v.fills)])) + "</div>" +
				(Number(v.idle_l) ? '<div class="dim">' + esc(t("{0} L idling allowance", [fmt(v.idle_l)])) + "</div>" : "") + "</td>" +
			'<td class="num">' + dist + "</td>" +
			"<td>" + esc(n[0]) + (n[1] ? '<div class="dim">' + esc(n[1]) + "</div>" : "") + '<div class="dim">' + esc(v.dates || "") + "</div>" +
				// Why the most exact view sets this source aside for the truck.
				(v.why ? '<div class="warn" style="font-weight:500;font-size:11.5px">' + esc(v.why) + "</div>" : "") + "</td>" +
			'<td class="num ' + tone(r, v.lp, v.km, v.src === "card") + '"><b>' + num(v.lp, 1) + '</b><div class="dim">' +
				esc(t("limit {0}", [fmt(r.normal_lp100)])) + "</div></td>" +
			'<td class="reason">' + reason_of(v.findings) + "</td>" +
			'<td class="num">' + (Number(v.risk) ? esc(t("{0} L", [fmt(v.risk)])) + '<div class="dim">' + esc(t("{0} SAR", [fmt(v.sar)])) + "</div>" : none) + "</td>";
	}

	function render_trucks(rows) {
		el.body.innerHTML = rows.map(function (r, i) {
			var km = km_used(r);
			var plate = '<td><span class="mono">' + esc(r.plate) + "</span>" + (r.platform_name ? '<div class="dim">' + esc(r.platform_name) + "</div>" : "") + "</td>";
			var vehicle = "<td>" + esc([r.brand, r.model].filter(Boolean).join(" ")) + '<div class="dim">' + esc(t(r.vehicle_class || "Heavy truck")) + "</div></td>";
			if (by) return '<tr class="click" data-i="' + i + '">' + view_cells(r, plate, vehicle) + "</tr>";
			return '<tr class="click" data-i="' + i + '">' +
				"<td>" + pill(r.verdict) + "</td>" + plate + vehicle +
				'<td class="num">' + esc(t("{0} L", [fmt(r.liters)])) + '<div class="dim">' + esc(t("{0} fills", [fmt(r.fills)])) + "</div></td>" +
				'<td class="num">' + (known(km) ? esc(t("{0} km", [fmt(km)])) : '<span class="dim">—</span>') + "</td>" +
				"<td>" + used_cell(r) + "</td>" +
				'<td class="num ' + lp_tone(r) + '"><b>' + num(r.lp100, 1) + '</b><div class="dim">' + esc(t("limit {0}", [fmt(r.normal_lp100)])) + "</div></td>" +
				'<td class="reason">' + reason(r) + "</td>" +
				'<td class="num">' + (Number(r.liters_at_risk)
					? esc(t("{0} L", [fmt(r.liters_at_risk)])) + '<div class="dim">' + esc(t("{0} SAR", [fmt(r.cost_at_risk)])) + "</div>"
					: '<span class="dim">—</span>') + "</td>" +
			"</tr>";
		}).join("");
		el.body.querySelectorAll("tr[data-i]").forEach(function (tr) {
			tr.addEventListener("click", function () { open_truck(rows[Number(tr.getAttribute("data-i"))]); });
		});
	}

	// Fill rows: the Fills tab (with the plate) or one truck's fills in its
	// dialog. Fills have no status of their own; their notes are for reference.
	function fill_rows(rows, with_plate) {
		return rows.map(function (r) {
			var note = fill_note_text(r);
			// A fill in a run that bought more than the truck could burn and hold.
			return "<tr" + (r.trip ? ' style="background:rgba(224,82,75,.10)"' : "") + ">" +
				(with_plate ? '<td><span class="mono">' + esc(r.plate) + "</span></td>" : "") +
				'<td class="nowrap">' + when(r.fill_time) + "</td>" +
				"<td>" + esc(r.station_branch || r.station) + '<div class="dim">' + esc(r.station_area) + "</div></td>" +
				'<td class="num">' + num(r.liters, 1) + "</td>" +
				'<td class="num">' + (Number(r.odometer) ? esc(fmt(r.odometer)) : '<span class="dim">—</span>') + "</td>" +
				'<td class="num">' + num(r.odometer_km_since_prev) + "</td>" +
				'<td class="num">' + num(r.gps_km_since_prev, 1) + "</td>" +
				"<td>" + esc(r.driver) + "</td>" +
				'<td class="reason dim">' + (note ? esc(note) : "—") + "</td>" +
			"</tr>";
		}).join("");
	}

	function fill_table(rows) {
		var head = [t("Time"), t("Station"), t("Liters"), t("Odometer"), t("Odometer km since last fill"), t("GPS km since last fill"),
			t("Driver"), t("Notes")];
		return "<table><thead><tr>" + head.map(function (h) { return "<th>" + esc(h) + "</th>"; }).join("") + "</tr></thead><tbody>" +
			fill_rows(rows, false) + "</tbody></table>";
	}

	function truck_facts(r) {
		var d = info.import || {}, out = [];
		function fact(k, v) {
			out.push('<div class="fue-fact"><div class="k">' + esc(k) + '</div><div class="v">' + v + "</div></div>");
		}
		function line(label, value) {
			return "<div>" + esc(label) + ": " + (known(value) ? esc(t("{0} km", [fmt(value)])) : '<span class="dim">—</span>') + "</div>";
		}

		fact(t("Fuel bought"), esc(t("{0} L in {1} fills · {2} SAR", [fmt(r.liters), fmt(r.fills), fmt(r.cost)])) +
			(r.drivers ? '<div class="dim">' + esc(t("Drivers: {0}", [r.drivers])) + "</div>" : ""));

		// A report analysed before the per-report table came has only these two.
		var old = !(r.by_report || []).length, km = km_used(r);
		if (old) fact(t("Consumption"), known(r.lp100)
			? '<b class="' + lp_tone(r) + '">' + esc(t("{0} L/100 km over {1} km, by {2}", [fmt(r.lp100, 1), fmt(km), BASIS[r.lp100_basis] || ""])) + "</b>" +
				(Number(km) < JUDGE_KM ? '<div class="dim">' + esc(t("Too short to judge (under {0} km)", [JUDGE_KM])) + "</div>" : "") +
				'<div class="dim">' + esc(t("Normal up to {0} · theft likely above {1} ({2})", [fmt(r.normal_lp100), fmt(r.theft_lp100), t(r.vehicle_class)])) + "</div>" +
				(known(r.peer_lp100) ? '<div class="dim">' + esc(t("Similar trucks: {0} L/100 km", [fmt(r.peer_lp100, 1)])) +
					(known(r.excess_pct) ? " (" + signed(r.excess_pct) + ")" : "") + "</div>" : "") +
				(known(r.idle_allowance_l) ? '<div class="dim">' + esc(t("{0} L allowed for {1} idle hours", [fmt(r.idle_allowance_l), fmt(r.idle_hours, 1)])) + "</div>" : "")
			: '<span class="dim">' + esc(t("Not enough distance to judge")) + "</span>");

		var off = Math.abs(Number(r.odometer_gap_pct) || 0) >= 25;
		if (old) fact(t("Distance and odometer"),
			line(t("GPS track"), r.gps_km) + line(t("IM report"), r.im_km) + line(t("Typed odometer"), r.odometer_km) +
			(known(r.odometer_gap_pct) ? '<div class="' + (off ? "no" : "dim") + '">' +
				esc(t("Odometer vs IM: {0}", [(Number(r.odometer_gap_pct) > 0 ? "+" : "") + fmt(r.odometer_gap_pct) + "%"])) + "</div>" : ""));

		if (Number(r.has_sensor)) {
			var miss = Number(r.missing_l) || 0;
			// Set aside when it sees only part of the fuel, or none of it.
			var aside = (r.findings || []).some(function (x) { return x.code === "sensor_low" || x.code === "sensor_dead"; });
			fact(t("Tank fuel sensor") + (d.fill_drain_period ? " · " + d.fill_drain_period : ""),
				esc(t("Paid for {0} L · seen arriving {1} L ({2} fills)", [fmt(r.sensor_card_l), fmt(r.sensor_fill_l), fmt(r.sensor_fills)])) +
				(miss > 0 ? '<div class="' + (aside ? "dim" : miss >= 60 ? "no" : "warn") + '">' +
					esc(aside ? t("{0} L not seen by the sensor (sensor not used)", [fmt(miss)]) : t("{0} L missing", [fmt(miss)])) + "</div>" : "") +
				'<div class="' + (Number(r.drain_l) > 0 ? "no" : "dim") + '">' +
					esc(t("Drained {0} L ({1} times) · slowly {2} L", [fmt(r.drain_l, 1), fmt(r.drains), fmt(r.slow_drain_l, 1)])) + "</div>" +
				'<div class="dim">' + esc(t("Burned {0} L · level {1} → {2} L", [fmt(r.sensor_consumed_l, 1), fmt(r.start_level), fmt(r.last_level)])) + "</div>");
		} else {
			fact(t("Tank fuel sensor"), '<span class="dim">' +
				esc(d.fill_drain_period ? t("No sensor data for this truck in the Fill-Drain report") : t("No IM Fill-Drain report uploaded")) + "</span>");
		}
		fact(t("Checked with"), esc(checked(r)) + (r.imei ? '<div class="dim">' + esc(t("IMEI {0}", [r.imei])) + "</div>" : ""));
		return '<div class="fue-facts">' + out.join("") + "</div>";
	}

	// Each source worked out on its own -- the typed odometer, the GPS track and
	// each IM report -- with what it takes from the other files, and which one
	// decided the status.
	function by_report(r) {
		var ways = r.by_report || [];
		if (!ways.length) return "";
		var none = '<span class="dim">—</span>';
		function dim(text) {
			return '<div class="dim">' + esc(text) + "</div>";
		}
		function note(html) {
			return '<div class="dim fue-by-note">' + html + "</div>";
		}
		var body = ways.map(function (w) {
			var name = used_names(w.src);
			var dist = known(w.km) ? esc(t("{0} km", [fmt(w.km)])) : none;
			if (w.odo) {
				dist += dim(w.src === "card" ? t("odometer {0} → {1}", [fmt(w.odo[0]), fmt(w.odo[1])])
					: t("typed odometer in these dates: {0} km", [fmt(w.odo[1] - w.odo[0])]));
			} else if (w.src === "gps" && known(w.km)) {
				dist += dim(t("first fill to last"));
			}
			var fuel = Number(w.fills) ? esc(t("{0} L", [fmt(w.liters)])) + dim(t("{0} fills after the first", [fmt(w.fills)])) : none;
			if (known(w.sensor_l)) fuel += dim(t("tank sensor: {0} L burned", [fmt(w.sensor_l)]));
			var idle = Number(w.idle_l) ? esc(t("{0} L", [fmt(w.idle_l)])) + dim(t("{0} idle h", [fmt(w.idle_h, 1)])) : none;
			var lp = known(w.lp) ? '<b class="' + tone(r, w.lp, w.km, w.src === "card") + '">' + esc(fmt(w.lp, 1)) + "</b>" : none;
			if (known(w.sensor_lp)) lp += dim(t("tank sensor: {0}", [fmt(w.sensor_lp, 1)]));
			return "<tr" + (w.used ? ' class="used"' : "") + ">" +
				"<td><b>" + esc(name[0]) + '</b> <span class="dim">' + esc(name[1]) + "</span>" +
					(w.used ? '<div><span class="tag">' + esc(t("Used for the status")) + "</span></div>" : dim(w.why || t("For comparison"))) + "</td>" +
				'<td class="nowrap">' + esc(w.dates) + "</td>" +
				'<td class="num">' + dist + '</td><td class="num">' + fuel + "</td>" +
				'<td class="num">' + idle + '</td><td class="num">' + lp + "</td></tr>";
		}).join("");
		var head = [t("Worked out from"), t("Dates"), t("Distance"), t("Fuel counted"), t("Idling allowance"), t("L/100 km")];
		var gap = Number(r.odometer_gap_pct);
		return '<div class="fue-sec"><div class="fue-sec-t">' + esc(t("Consumption by each report")) + "</div>" +
			'<div class="fue-by-wrap"><table class="fue-by"><thead><tr>' +
				head.map(function (h, i) { return '<th class="' + (i > 1 ? "num" : "") + '">' + esc(h) + "</th>"; }).join("") +
			"</tr></thead><tbody>" + body + "</tbody></table></div>" +
			note(esc(t("Normal up to {0} · theft likely above {1} ({2})", [fmt(r.normal_lp100), fmt(r.theft_lp100), t(r.vehicle_class)])) +
				(known(r.peer_lp100) ? " · " + esc(t("Similar trucks: {0} L/100 km", [fmt(r.peer_lp100, 1)])) : "") +
				(known(r.odometer_gap_pct) ? ' · <span class="' + (Math.abs(gap) >= 25 ? "no" : "") + '">' +
					esc(t("Odometer vs IM: {0}", [(gap > 0 ? "+" : "") + fmt(gap) + "%"])) + "</span>" : "")) +
			note(esc(ways.some(function (w) { return w.used; })
				? t("The status uses the most exact one that holds up: GPS first, then IM's report, then the typed odometer.")
				: t("Not enough distance to judge"))) +
			note(esc(t("Each row is worked out on its own: the liters bought after the first fill in its dates (they replace what was burned over that distance), less the fuel allowed for idling, per 100 km. The IM reports take their liters from the fuel card, and the idle hours come from IM."))) +
		"</div>";
	}

	function open_truck(r) {
		var d = new frappe.ui.Dialog({ title: r.plate + " · " + t(r.verdict), size: "extra-large" });
		d.$body.html(dlg() + esc(t("Loading…")) + "</div>");
		d.show();
		call("get_fills", { fuel_import: imp, plate_key: r.plate_key || "", plate: r.plate_key ? "" : r.plate, limit: 2000, lang: shown() })
			.then(function (res) {
				var why = (r.findings || []).length
					? r.findings.map(function (x) {
						return '<li class="' + (LEVEL_TONE[x.level] || "gray") + '"><span class="dot"></span><span>' + esc(x.text) + "</span></li>";
					}).join("")
					: '<li class="green"><span class="dot"></span><span>' + esc(t("Nothing unusual found.")) + "</span></li>";
				d.$body.html(DIALOG_CSS + dlg() +
					'<div class="fue-dlg-head">' + pill(r.verdict) + " <b>" + esc([r.brand, r.model].filter(Boolean).join(" ")) + "</b>" +
						'<span class="dim">' + esc(t(r.vehicle_class || "Heavy truck")) + "</span></div>" +
					'<div class="fue-sec"><div class="fue-sec-t">' + esc(t("Why this status")) + '</div><ul class="fue-why">' + why + "</ul></div>" +
					by_report(r) +
						truck_facts(r) +
					'<div class="fue-sec"><div class="fue-sec-t">' + esc(t("Fills")) + "</div>" +
						'<div class="dim" style="margin-bottom:6px">' +
							esc(t("The status comes from this truck's fuel against its distance over all its fills. Notes on single fills are for reference only.")) +
						'</div><div class="fue-dlg-wrap">' + fill_table(res.rows || []) + "</div></div>" +
				"</div>");
			});
	}

	function pager(res) {
		var total = res.total || 0, shown_n = (res.rows || []).length;
		el.foot.innerHTML = total
			? "<span>" + esc(t("{0}–{1} of {2}", [fmt(start + 1), fmt(start + shown_n), fmt(total)])) + "</span><span>" +
				(start > 0 ? '<a href="#" class="prev">' + esc(t("Previous")) + "</a>" : "") +
				(start + shown_n < total ? '<a href="#" class="next">' + esc(t("Next")) + "</a>" : "") + "</span>"
			: "";
		var prev = el.foot.querySelector(".prev"), next = el.foot.querySelector(".next");
		if (prev) prev.addEventListener("click", function (e) { e.preventDefault(); start = Math.max(0, start - limit); load_rows(); });
		if (next) next.addEventListener("click", function (e) { e.preventDefault(); start += limit; load_rows(); });
	}

	// ------------------------------------------------------------- actions

	// A new report: the fuel-card export plus, optionally, IM's two reports.
	// `add_to`: add or replace the IM reports of that report instead.
	function upload(add_to) {
		// A new report starts with the limits of the report on screen; adding IM
		// reports keeps its own (they are changed on their own, from Limits).
		var fields = add_to ? [] : limit_fields().concat([{ fieldtype: "Section Break", fieldname: "files_sec" }]);
		if (!add_to) {
			fields.push({ fieldtype: "Attach", fieldname: "card", label: t("1. Fuel-card report"), reqd: 1, options: XLSX,
				description: t("From the fuel company: one row per fill. Required.") });
		}
		fields.push(
			{ fieldtype: "Attach", fieldname: "fill_drain", label: t("2. IM Fill-Drain report"), options: XLSX,
				description: t("Same dates as the fuel card. Shows the fuel the tank sensor saw arrive or leave.") },
			{ fieldtype: "Attach", fieldname: "consumption", label: t("3. IM Fuel Consumption report"), options: XLSX,
				description: t("Same dates as the fuel card. Adds IM's distance and idle hours.") },
			{ fieldtype: "HTML", fieldname: "hint",
				options: dlg() + '<div class="text-muted small">' + esc(t("Excel files (.xlsx). The order does not matter: each file is recognised by what is in it.")) + "</div></div>" }
		);
		var dialog = new frappe.ui.Dialog({
			title: add_to ? t("Add IM reports") : t("New fuel report"),
			fields: fields,
			primary_action_label: add_to ? t("Add and re-analyse") : t("Analyse"),
			primary_action: function (v) {
				var files = [v.card, v.fill_drain, v.consumption].filter(Boolean);
				if (!files.length) return frappe.msgprint(t("Choose at least one file."));
				var args = { files: files, fuel_import: add_to || "", lang: shown() };
				if (!add_to) {
					args.normal_limit = Number(v.normal_limit);
					args.theft_limit = Number(v.theft_limit);
					if (!(args.normal_limit > 0) || !(args.theft_limit > args.normal_limit)) {
						return frappe.msgprint(t("The theft limit must be above the normal limit."));
					}
				}
				frappe.call({
					method: M + "upload_files",
					args: args,
					freeze: true,
					freeze_message: t("Reading the files…"),
				}).then(function (r) {
					var m = (r && r.message) || {};
					dialog.hide();
					frappe.show_alert({ message: esc(t("Queued: {0} fills. This takes a few minutes.", [fmt(m.fills)])), indicator: "blue" });
					if ((m.warnings || []).length) {
						frappe.msgprint({ title: t("Check the IM reports' dates"), indicator: "orange", message: m.warnings.map(esc).join("<br><br>") });
					}
					load_imports(m.name);
				});
			},
		});
		dialog.show();
	}

	// The report's link for someone without an account -- this report only,
	// read-only -- made on the first click and copied on every click.
	function copy_link() {
		if (!imp) return;
		call("share_link", { fuel_import: imp }).then(function (r) {
			var url = r.url || "";
			if (!url) return;
			copy_text(url);
			info.shared = true;
			update_share();
			frappe.show_alert({ indicator: "green", message: esc(t("Link copied. Anyone with it can open this report without an account, read-only. It never expires: it works until Stop sharing is pressed.")) +
				'<div style="font-size:11px;direction:ltr;word-break:break-all;margin-top:4px">' + esc(url) + "</div>" }, 8);
		});
	}
	function stop_sharing() {
		if (!imp) return;
		frappe.confirm(esc(t("Stop this link? Whoever has it can no longer open the report.")), function () {
			call("share_link", { fuel_import: imp, stop: 1 }).then(function () {
				info.shared = false;
				update_share();
				frappe.show_alert({ message: esc(t("The link is stopped.")), indicator: "orange" });
			});
		});
	}
	function update_share() {
		var b = el.headright.querySelector(".fue-unshare");
		if (b) b.style.display = info.shared ? "" : "none";
	}
	// The clipboard API needs https; the desk here runs on http, so fall back
	// to a hidden text box and the copy command.
	function copy_text(text) {
		if (typeof navigator !== "undefined" && navigator.clipboard && typeof window !== "undefined" && window.isSecureContext) {
			navigator.clipboard.writeText(text);
			return;
		}
		var box = document.createElement("textarea");
		box.value = text;
		box.style.position = "fixed";
		box.style.opacity = "0";
		document.body.appendChild(box);
		if (box.select) box.select();
		if (document.execCommand) document.execCommand("copy");
		document.body.removeChild(box);
	}

	// The heavy-truck limits, starting from the report on screen.
	function limit_fields() {
		var lim = info.import || {};
		return [
			{ fieldtype: "Float", fieldname: "normal_limit", label: t("Normal consumption up to (L/100 km)"), reqd: 1,
				default: Number(lim.normal_limit) || 55,
				description: t("For heavy trucks. Above it a truck is Suspicious, and what it burned above it is counted as stolen fuel.") },
			{ fieldtype: "Float", fieldname: "theft_limit", label: t("Theft likely above (L/100 km)"), reqd: 1,
				default: Number(lim.theft_limit) || 70,
				description: t("For heavy trucks. Medium trucks (30 / 42) and light vehicles (16 / 24) keep their own limits.") },
		];
	}
	// The limits on their own: saved, and the report analysed again on the
	// files it already has -- nothing to upload.
	function limits_dialog() {
		if (!imp) return;
		var d = new frappe.ui.Dialog({
			title: t("Consumption limits"),
			fields: limit_fields(),
			primary_action_label: t("Save and re-analyse"),
			primary_action: function (v) {
				var normal = Number(v.normal_limit), theft = Number(v.theft_limit);
				if (!(normal > 0) || !(theft > normal)) return frappe.msgprint(t("The theft limit must be above the normal limit."));
				call("set_limits", { fuel_import: imp, normal_limit: normal, theft_limit: theft }).then(function () {
					d.hide();
					watch({ progress: "Queued" });
				});
			},
		});
		d.show();
	}
	function update_limits() {
		var b = el.headright.querySelector(".fue-limits"), d = info.import || {};
		if (b) b.textContent = t("Limits: {0} / {1}", [fmt(Number(d.normal_limit) || 55), fmt(Number(d.theft_limit) || 70)]);
	}

	function rerun() {
		if (!imp) return;
		frappe.confirm(esc(t("Read GPS again for every truck in this report and redo all the checks?")), function () {
			call("reanalyse", { fuel_import: imp }).then(function () { watch({ progress: "Queued" }); });
		});
	}

	function help() {
		var limits = (info.limits || []).map(function (l) {
			return "<li>" + esc(t(l.class)) + ": " + esc(t("normal up to {0}, theft likely above {1}", [l.normal, l.theft])) + "</li>";
		}).join("");
		var d = new frappe.ui.Dialog({ title: t("How it works"), size: "large" });
		d.$body.html(DIALOG_CSS + dlg("fue-help-body") +
			"<p>" + esc(t("Every truck gets one status:")) + "</p>" +
			'<ul class="fue-why">' + STATUSES.map(function (st) {
				return '<li class="' + TONE[st] + '"><span class="dot"></span><span><b>' + esc(t(st)) + "</b> — " + esc(HINT[st]) + "</span></li>";
			}).join("") + "</ul>" +
			'<div class="fue-sec"><div class="fue-sec-t">' + esc(t("What is checked")) + "</div></div><ul>" +
				"<li>" + esc(t("How much does it burn? Liters per 100 km against the limit for its class:")) + (limits ? "<ul>" + limits + "</ul>" : "") + "</li>" +
				"<li>" + esc(t("Did the fuel reach the tank? The IM Fill-Drain report shows how much fuel the tank sensor saw arrive, and any fuel drained out.")) + "</li>" +
				"<li>" + esc(t("Does the odometer match? The odometer typed at the pump against the distance IM measured.")) + "</li>" +
				"<li>" + esc(t("Shown as notes only, never changing the status: refuelling after almost no driving, twice within a few hours, fills larger than usual or than the tank, and the tracker being off.")) + "</li>" +
			'</ul><p class="dim">' + esc(t("Idle time (air-conditioning, fridge units) is allowed for before consumption is judged, using IM's idle hours.")) + "</p></div>");
		d.show();
	}

	// The Trucks export when every truck is worked out from one source.
	function view_cols() {
		var of = function (key) { return function (x) { return x.view ? x.view[key] : ""; }; };
		return [["Status", function (x) { return x.view ? t(x.view.status) : "—"; }], ["Plate", "plate"], ["Name on IM", "platform_name"],
			["Brand", "brand"], ["Model", "model"], ["Class", function (x) { return t(x.vehicle_class); }], ["Branch", "branch"],
			["Worked out from", function (x) { return source_name(by) + (x.view && x.view.why ? " — " + x.view.why : ""); }],
			["Dates", of("dates")], ["Fuel counted", of("liters")],
			["Idling allowance", of("idle_l")], ["Distance", of("km")], ["L/100 km", of("lp")], ["Normal up to", "normal_lp100"],
			["Theft likely above", "theft_lp100"], ["Stolen fuel (L)", of("risk")], ["Stolen fuel (SAR)", of("sar")],
			["Reasons", function (x) { return x.view ? x.view.findings.map(function (y) { return y.text; }).join("; ") : x.view_why || ""; }]];
	}

	function export_csv() {
		if (!imp) return;
		var trucks = view === "trucks";
		var args = trucks ? truck_args({ start: 0, limit: 100000 }) : fill_args({ start: 0, limit: 100000 });
		frappe.call({ method: M + (trucks ? "get_vehicles" : "get_fills"), args: args, freeze: true, freeze_message: t("Building the file…") })
			.then(function (r) {
				var rows = ((r && r.message) || {}).rows || [];
				if (!rows.length) return frappe.msgprint(t("Nothing to export."));
				var cols = trucks && by ? view_cols() : trucks
					? [["Status", function (x) { return t(x.verdict); }], ["Plate", "plate"], ["Name on IM", "platform_name"], ["Brand", "brand"],
						["Model", "model"], ["Class", function (x) { return t(x.vehicle_class); }], ["Branch", "branch"], ["Checked with", checked],
						["Fills", "fills"], ["Liters", "liters"], ["Cost (SAR)", "cost"], ["GPS km", "gps_km"], ["IM km", "im_km"],
						["Odometer km", "odometer_km"], ["Odometer vs IM (%)", "odometer_gap_pct"], ["L/100 km", "lp100"],
						["Report used", used_text], ["Normal up to", "normal_lp100"],
						["Theft likely above", "theft_lp100"], ["Paid for (L)", "sensor_card_l"], ["Seen in tank (L)", "sensor_fill_l"],
						["Missing (L)", "missing_l"], ["Drained (L)", "drain_l"], ["Stolen fuel (L)", "liters_at_risk"], ["Stolen fuel (SAR)", "cost_at_risk"],
						["Reasons", "issues"]]
					: [["Plate", "plate"], ["Time", "fill_time"], ["Invoice", "invoice_no"], ["Driver", "driver"], ["Station", "station"],
						["Area", "station_area"], ["Liters", "liters"], ["Price", "price"], ["Cost", "cost"], ["Odometer", "odometer"],
						["Hours since last fill", "hours_since_prev"], ["GPS km since last fill", "gps_km_since_prev"],
						["Odometer km since last fill", "odometer_km_since_prev"], ["Notes", fill_note_text]];
				var cell = function (v) { return '"' + String(v === null || v === undefined ? "" : v).replace(/"/g, '""') + '"'; };
				var csv = [cols.map(function (c) { return cell(t(c[0])); }).join(",")].concat(rows.map(function (row) {
					return cols.map(function (c) { return cell(typeof c[1] === "function" ? c[1](row) : row[c[1]]); }).join(",");
				})).join("\n");
				var a = document.createElement("a");
				// Leading BOM so Excel reads Arabic as UTF-8.
				a.href = "data:text/csv;charset=utf-8," + encodeURIComponent("﻿" + csv);
				a.download = "fuel-efficiency-" + (trucks ? "trucks" : "fills") + ".csv";
				document.body.appendChild(a);
				a.click();
				document.body.removeChild(a);
			});
	}

	// ------------------------------------------------------------ progress

	function show_progress(text, done, total) {
		el.progress.style.display = "";
		el.ptext.textContent = t_progress(text) || t("Working…");
		el.pfill.classList.toggle("sweep", !total);
		el.pfill.style.width = total ? Math.round((done * 100) / total) + "%" : "";
	}

	function watch(p) {
		show_progress(p.progress || "Queued");
		if (poller) return;
		poller = setInterval(function () {
			if (!imp || !(root_element.host && root_element.host.isConnected)) return stop_watch();
			call("get_progress", { fuel_import: imp }).then(function (q) {
				if (q.status !== "Queued" && q.status !== "Running") {
					stop_watch();
					load_imports(imp);
				} else {
					show_progress(q.progress || q.status);
				}
			});
		}, 4000);
	}

	function stop_watch() {
		if (poller) clearInterval(poller);
		poller = null;
		el.progress.style.display = "none";
	}

	frappe.realtime.on("fuel_efficiency_progress", function (d) {
		if (!d || d.fuel_import !== imp) return;
		if (d.stage === "done" || d.stage === "failed" || d.stage === "cancelled") {
			stop_watch();
			load_imports(imp);
			return;
		}
		show_progress(d.text, d.done, d.total);
	});

	var saved = null;
	try {
		saved = localStorage.getItem("fue_lang");
	} catch (e) {
		// no storage: follow the desk language
	}
	set_lang(saved || (String((frappe.boot && frappe.boot.lang) || "").indexOf("ar") === 0 ? "ar" : "en"));
})();

style:
/* Logical properties (inline-start/end, text-align:start/end) so the page
   mirrors cleanly when the desk runs in Arabic. */
.fue { font-size:13px; line-height:1.5; }
.fue .fue-head { display:flex; justify-content:space-between; align-items:flex-end; flex-wrap:wrap; gap:12px; margin-bottom:12px; }
.fue .fue-title { margin:0; font-size:20px; font-weight:600; }
.fue .fue-when { font-size:12px; color:var(--text-muted); margin-top:2px; }
.fue .fue-headright { display:flex; gap:6px; align-items:center; flex-wrap:wrap; }
.fue .fue-headright .btn .fue-svg { vertical-align:-2px; margin-inline-end:5px; }
.fue .fue-headright .fue-copy { color:var(--primary,#2490ef); font-weight:600; }
.fue .fue-headright select { height:30px; font-size:12.5px; max-width:340px; padding:2px 8px;
	border:1px solid var(--border-color); border-radius:8px; background:var(--card-bg); color:var(--text-color); }

.fue .fue-notes { margin-bottom:14px; font-size:12px; }
.fue .fue-notes:empty { display:none; }
.fue .fue-chips { display:flex; flex-wrap:wrap; gap:6px; align-items:center; color:var(--text-muted); }
.fue .fue-chip { padding:2px 10px; border-radius:999px; background:var(--control-bg,rgba(120,120,120,.12)); }
.fue .fue-chip.ok { background:rgba(58,167,109,.14); color:#1f7a44; }
.fue .fue-note { color:var(--text-muted); margin-top:6px; }
.fue .fue-warn { margin-top:8px; padding:8px 12px; border-radius:8px; background:rgba(232,163,61,.14); color:#8a5300; }
.fue .fue-link { color:var(--primary,#2490ef); text-decoration:none; cursor:pointer; }
.fue .fue-link:hover { text-decoration:underline; }

.fue .fue-progress { position:relative; height:32px; border-radius:8px; overflow:hidden;
	background:var(--control-bg,rgba(120,120,120,.15)); margin-bottom:12px; }
.fue .fue-cancel { position:absolute; inset-inline-end:6px; top:50%; transform:translateY(-50%); }
.fue .fue-pfill { position:absolute; top:0; bottom:0; inset-inline-start:0; width:0; background:var(--primary,#2490ef);
	opacity:.25; transition:width .4s; }
.fue .fue-pfill.sweep { width:35%; animation:fue-sweep 1.1s ease-in-out infinite; }
@keyframes fue-sweep { 0% { inset-inline-start:-35%; } 100% { inset-inline-start:100%; } }
.fue .fue-ptext { position:relative; line-height:32px; padding:0 12px; font-size:12px; }

.fue .fue-cards { display:grid; grid-template-columns:repeat(auto-fit,minmax(190px,1fr)); gap:12px; margin-bottom:10px; }
.fue .fue-card { display:flex; flex-direction:row; align-items:flex-start; gap:12px; text-align:start; padding:14px 16px;
	border:1px solid var(--border-color); border-inline-start-width:4px; border-radius:12px; background:var(--card-bg);
	font:inherit; color:inherit; cursor:pointer; transition:box-shadow .15s; }
.fue .fue-card:hover { box-shadow:0 2px 12px rgba(0,0,0,.07); }
.fue .fue-card:focus { outline:none; }
.fue .fue-card.on { box-shadow:0 0 0 2px var(--primary,#2490ef); }
.fue .fue-card.red { border-inline-start-color:#e0524b; }
.fue .fue-card.amber { border-inline-start-color:#e8a33d; }
.fue .fue-card.green { border-inline-start-color:#3aa76d; }
.fue .fue-card.risk { cursor:default; border-inline-start-color:#98a1a9; }
.fue .fue-card.risk:hover { box-shadow:none; }
.fue .fue-card-body { display:flex; flex-direction:column; gap:2px; min-width:0; }
/* Each status wears its own colour: the icon badge, the label and the edge. */
.fue .fue-card-ico { flex:none; width:40px; height:40px; border-radius:12px; display:grid; place-items:center; }
.fue .fue-card.red .fue-card-ico { background:rgba(224,82,75,.14); color:#c2413b; }
.fue .fue-card.amber .fue-card-ico { background:rgba(232,163,61,.18); color:#b86e00; }
.fue .fue-card.green .fue-card-ico { background:rgba(58,167,109,.15); color:#1f7a44; }
.fue .fue-card.risk .fue-card-ico { background:rgba(36,144,239,.12); color:var(--primary,#2490ef); }
.fue .fue-card-label { display:flex; align-items:center; gap:6px; font-size:12.5px; font-weight:600; color:var(--text-muted); }
.fue .fue-card.red .fue-card-label { color:#c2413b; }
.fue .fue-card.amber .fue-card-label { color:#b86e00; }
.fue .fue-card.green .fue-card-label { color:#1f7a44; }
.fue .fue-card-n { font-size:26px; font-weight:700; line-height:1.25; }
.fue .fue-card-n small { font-size:12.5px; font-weight:500; color:var(--text-muted); }
.fue .fue-card-hint { font-size:11.5px; color:var(--text-muted); }
.fue .dot { width:8px; height:8px; border-radius:50%; background:currentColor; display:inline-block; flex:none; }
.fue .red .dot { color:#e0524b; }
.fue .amber .dot { color:#e8a33d; }
.fue .green .dot { color:#3aa76d; }
.fue .gray .dot { color:#98a1a9; }

.fue .fue-stats { display:flex; flex-wrap:wrap; gap:4px 18px; font-size:12px; color:var(--text-muted); margin:2px 2px 18px; }
.fue .fue-stats b { color:var(--text-color); font-weight:600; }
.fue .fue-stat { display:inline-flex; align-items:center; gap:5px; }
.fue .fue-stat .fue-svg { flex:none; opacity:.8; }

.fue .fue-bar { display:flex; flex-wrap:wrap; justify-content:space-between; align-items:center; gap:10px; margin-bottom:10px; }
.fue .fue-tabs { display:inline-flex; gap:4px; padding:3px; border-radius:10px; background:var(--control-bg,rgba(120,120,120,.1)); }
.fue .fue-tabs a { padding:5px 16px; border-radius:8px; color:var(--text-muted); text-decoration:none; font-weight:500; }
.fue .fue-tabs a.on { background:var(--card-bg); color:var(--text-color); box-shadow:0 1px 3px rgba(0,0,0,.1); }
.fue .fue-bar-end { font-size:12px; }
/* Which source every truck is worked out from. */
.fue .fue-by-pick { display:inline-flex; align-items:center; gap:8px; flex-wrap:wrap; }
.fue .fue-by-pick > span { font-size:12px; font-weight:600; color:var(--text-muted); }
.fue .fue-view-note { flex-basis:100%; color:var(--primary,#2490ef); font-weight:600; margin-bottom:2px; }

.fue .fue-wrap { border:1px solid var(--border-color); border-radius:12px; overflow-x:auto; background:var(--card-bg); }
.fue table { width:100%; margin:0; border-collapse:collapse; font-size:12.5px; }
.fue thead { background:var(--subtle-fg,rgba(120,120,120,.04)); }
.fue th { font-size:11.5px; color:var(--text-muted); font-weight:600; padding:10px 12px 4px; text-align:start; white-space:nowrap; }
.fue th.num { text-align:end; }
/* Column headings sort: up, down, then back to the report's own order. */
.fue .fue-sort { all:unset; display:inline-flex; align-items:center; gap:4px; cursor:pointer; font:inherit; color:inherit; white-space:nowrap; }
.fue .fue-sort:hover, .fue .fue-sort.on { color:var(--text-color); }
.fue .fue-sort:focus-visible { outline:2px solid var(--primary,#2490ef); outline-offset:2px; border-radius:4px; }
.fue .fue-arrow { font-size:10px; opacity:.4; }
.fue .fue-sort.on .fue-arrow { opacity:1; color:var(--primary,#2490ef); }
.fue .fue-filter-row th { padding:2px 8px 10px; border-bottom:1px solid var(--border-color); }
.fue .fue-filter-row select, .fue .fue-filter-row input { width:100%; min-width:96px; height:28px; font-size:12px; font-weight:400;
	padding:1px 6px; border:1px solid var(--border-color); border-radius:7px; background:var(--card-bg); color:var(--text-color); }
.fue .fue-filter-row .on { border-color:var(--primary,#2490ef); box-shadow:0 0 0 1px var(--primary,#2490ef) inset; }
.fue td { padding:10px 12px; border-bottom:1px solid var(--border-color); vertical-align:top; }
.fue tbody tr:last-child td { border-bottom:none; }
.fue tr.click { cursor:pointer; }
.fue tr.click:hover td { background:var(--control-bg,rgba(120,120,120,.06)); }
.fue .num { text-align:end; white-space:nowrap; }
.fue .nowrap { white-space:nowrap; }
.fue .reason { min-width:220px; max-width:420px; }
.fue .mono { font-family:var(--font-stack-mono,monospace); font-size:12px; white-space:nowrap; direction:ltr; unicode-bidi:isolate; }
.fue .dim { color:var(--text-muted); font-size:11.5px; }
.fue .yes { color:#1f7a44; }
.fue .no { color:#c2413b; font-weight:600; }
.fue .warn { color:#b86e00; font-weight:600; }
.fue .pill { display:inline-flex; align-items:center; gap:5px; padding:2px 10px; border-radius:999px; font-size:11.5px; font-weight:600; white-space:nowrap; }
.fue .pill.red { background:rgba(224,82,75,.14); color:#b3261e; }
.fue .pill.amber { background:rgba(232,163,61,.18); color:#8a5300; }
.fue .pill.green { background:rgba(58,167,109,.15); color:#1f7a44; }
.fue .pill.gray { background:rgba(120,120,120,.14); color:var(--text-muted); }

.fue .fue-empty { padding:36px 16px; text-align:center; color:var(--text-muted); }
.fue .fue-empty .big { font-size:15px; color:var(--text-color); font-weight:600; margin-bottom:8px; }
.fue .fue-empty .steps { display:inline-block; text-align:start; margin:0; padding-inline-start:20px; }
.fue .fue-foot { display:flex; justify-content:space-between; flex-wrap:wrap; gap:8px; margin-top:10px; font-size:12px; color:var(--text-muted); }
.fue .fue-foot a { color:var(--primary,#2490ef); text-decoration:none; margin-inline-start:14px; }
